def maximumDetonation(bombs: list[list[int]]) -> int:
    n = len(bombs)
    from collections import defaultdict
    adj = defaultdict(list)
    for i in range(n):
        x1, y1, r1 = bombs[i]
        for j in range(n):
            if i != j:
                x2, y2, _ = bombs[j]
                if (x1 - x2) ** 2 + (y1 - y2) ** 2 <= r1 ** 2:
                    adj[i].append(j)
    def dfs(u, visited):
        visited.add(u)
        for v in adj[u]:
            if v not in visited:
                dfs(v, visited)
    ans = 0
    for i in range(n):
        vis = set()
        dfs(i, vis)
        ans = max(ans, len(vis))
    return ans

